pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    StaxLPStaking c;

    function setUp() public {
        c = new StaxLPStaking(address(this), address(this));
    }

    function _test(address distributor) internal {
        try c.setRewardDistributor(distributor) {} catch { return; }
        assertTrue(c.rewardDistributor() == distributor);
    }

    function testFuzz_test(address distributor) public {
        _test(distributor);
    }

    receive() external payable {}
}
